def _idea(i, title, summary, tags, hours_ago, duration_ms, related=None, status="ok", collection_id=None):
    return {
        "id": f"idea_{i:02d}",
        "title": title,
        "summary": summary,
        "transcript": summary,
        "tags": tags,
        "status": status,
        "related": related or [],
        "extension": {},
        "collectionId": collection_id,
        "audioUrl": None,
        "createdAt": NOW - int(hours_ago * 3600 * 1000),
        "durationMs": duration_ms,
    }


